class Solution:
    def heightOfSpecialBinaryTree(self, root: Optional[TreeNode]) -> int:
        def h(node):
            if not node:
                return -1
            if not node.left and not node.right:
                return 0
            return 1 + max(h(node.left), h(node.right))
        return h(root)

