class Solution:
    def heightOfSpecialBinaryTree(self, root: Optional[TreeNode]) -> int:
        from collections import deque
        q = deque([(root, 0)])
        seen = {id(root)}
        h = 0
        while q:
            node, d = q.popleft()
            h = max(h, d)
            for ch in (node.left, node.right):
                if ch and id(ch) not in seen:
                    seen.add(id(ch))
                    q.append((ch, d + 1))
        return h

