int heightOfSpecialBinaryTree(TreeNode* root) {
    queue<pair<TreeNode*, int>> q;
    unordered_set<TreeNode*> seen{root};
    q.push({root, 0});
    int h = 0;
    while (!q.empty()) {
        auto [node, d] = q.front(); q.pop();
        h = max(h, d);
        for (TreeNode* ch : {node->left, node->right})
            if (ch && !seen.count(ch)) { seen.insert(ch); q.push({ch, d + 1}); }
    }
    return h;
}

