public int heightOfSpecialBinaryTree(TreeNode root) {
    Deque<Object[]> q = new ArrayDeque<>();
    Set<TreeNode> seen = new HashSet<>();
    q.push(new Object[]{root, 0});
    seen.add(root);
    int h = 0;
    while (!q.isEmpty()) {
        Object[] top = q.poll();
        TreeNode node = (TreeNode) top[0];
        int d = (Integer) top[1];
        h = Math.max(h, d);
        for (TreeNode ch : new TreeNode[]{node.left, node.right})
            if (ch != null && seen.add(ch)) q.push(new Object[]{ch, d + 1});
    }
    return h;
}

